public function view($id=null) {
    if (!$id) {
        throw new \Cake\Error\NotFoundException('Produkt wurde nicht gefunden');
    }
    $query = $this->Products->find();
    $query->where(['Products.id'=>$id]);
    $query->contain([
        'Channels',
        'Tags'
    ]);
    $product = $query->first();

    // wrong sql -- also when i rename `query` above  to something else
    $unlinkedTags = $this->Products->Tags->getUnlinkedTags($product->channel->id) ;
