}

public function test($id=null) {
    // correct result and sql
    $unlinkedTags = $this->Products->Tags->getUnlinkedTags($id);
    debug($unlinkedTags);
}


/**
 * function in TagsTable
 */
public function getUnlinkedTags($channel_id) {
    $linked_tag_ids = $this->find();
    $linked_tag_ids
        ->select(['id'])
        ->matching('Products', function($q) use ($channel_id) {
            return $q->where(['Products.channel_id' => $channel_id]);
        });
    $query = $this->find();
    $query->where(['id NOT IN'=>$linked_tag_ids]);

    $tags = $query->all();

    return $tags;
}
