namespace App\Model\Table;
use Cake\ORM\Table;

class TagsTable extends Table {

    public function initialize(array $config) {
        $this->addBehavior('Timestamp');
        $this->hasMany('TagsProducts');
    }


    public function getUnlinkedTags($channel_id) {
        // get tags connected to products per channel 
        $linked_tag_ids = $this->find();
        $linked_tag_ids
            ->select(['id'])
            ->matching('TagsProducts.Products', function($q) use ($channel_id) {
                return $q->where(['Products.channel_id' => $channel_id]);
            });
        $query = $this->find();
        $query->where(['id NOT IN'=>$linked_tag_ids]);

        $tags = $query->all();

        return $tags;
    }
}
